MainWindow::~MainWindow(){if(desktop_){desktop_->kill();desktop_->waitForFinished(1000);}if(host_){host_->kill();host_->waitForFinished(1000);}if(transfer_){transfer_->kill();transfer_->waitForFinished(1000);}}
void MainWindow::savePreferences(){QSettings p;p.setValue("stateDirectory",state());p.setValue("lastPeer",target());p.setValue("bitrate",bitrate_->value());}
void MainWindow::openAdmin(){QFile f(state()+"/agent.json");if(!f.open(QIODevice::ReadOnly)||f.size()>65536){QMessageBox::information(this,"RemoteDesk",QStringLiteral("请先配置服务器并完成注册。"));return;}auto j=QJsonDocument::fromJson(f.readAll()).object();QUrl url(j["server"].toString());if(url.scheme()!="https"||url.host().isEmpty()||!url.userInfo().isEmpty())return;url.setPath("/admin/");url.setQuery(QString());url.setFragment(QString());QDesktopServices::openUrl(url);}
void MainWindow::identity(){
 if(!QFileInfo::exists(state()+"/public-identity.json")){localID_.clear();deviceID_->setText(QStringLiteral("尚未初始化"));identity_->setText(QStringLiteral("先配置服务器并注册，设备上线后即可在后台查看。"));devices_->setRowCount(0);return;}
 command({"identity","--state",state()},[this](bool ok,QByteArray b){if(!ok)return;auto j=QJsonDocument::fromJson(b).object();localID_=j["id"].toString();deviceID_->setText(localID_.mid(0,4)+" "+localID_.mid(4,4)+" "+localID_.mid(8,4));identity_->setText(QStringLiteral("%1\n公钥指纹：%2").arg(j["name"].toString(),j["fingerprint"].toString()));savePreferences();refreshPeers();});
}
